// ParseParams converts a param string slice (key=value pairs) into Parameters.
func ParseParams(raw []string) ([]engine.Parameter, error) {
        var params []engine.Parameter
        for _, kv := range raw {
                parts := strings.SplitN(kv, "=", 2)
                if len(parts) != 2 {
                        return nil, fmt.Errorf("invalid parameter: %s (expected key=value)", kv)
                }
                val, err := strconv.ParseFloat(parts[1], 64)
                if err != nil {
                        return nil, fmt.Errorf("invalid parameter value for %s: %s", parts[0], parts[1])
                }
                params = append(params, engine.Parameter{Name: parts[0], Value: val})
        }
        return params, nil
}
