package engine

import (
        "fmt"
        "math/rand"
        "time"
)

// ExperimentType enumerates supported experiment categories.
type ExperimentType string

const (
        TypeMonteCarlo ExperimentType = "montecarlo"
        TypeMatrix     ExperimentType = "matrix"
        TypeODE        ExperimentType = "ode"
        TypeStats      ExperimentType = "stats"
)

// Parameter holds a single experiment parameter.
type Parameter struct {
        Name  string
        Value float64
}

// Result holds raw experiment output.
type Result struct {
        ExperimentName string
        Timestamp      time.Time
        Parameters     []Parameter
        Values         []float64
        Labels         []string
        Metadata       map[string]string
}

// ExperimentFunc is the signature for all experiment backends.
// It takes a name, parameters, and returns a Result or error.
type ExperimentFunc func(name string, params []Parameter) (*Result, error)

// Global registry of experiment backends.
var registry = map[string]ExperimentFunc{}

// Global random source used by all experiments (legacy: not reproducible).
var GlobalRand = rand.New(rand.NewSource(time.Now().UnixNano()))

// Register adds an experiment backend to the registry.
func Register(name string, fn ExperimentFunc) {
        registry[name] = fn
}

// Get retrieves an experiment backend by name.
func Get(name string) (ExperimentFunc, error) {
        fn, ok := registry[name]
        if !ok {
                return nil, fmt.Errorf("unknown experiment: %s", name)
        }
        return fn, nil
}

// List returns all registered experiment names.
func List() []string {
        names := make([]string, 0, len(registry))
        for k := range registry {
                names = append(names, k)
        }
        return names
}

// GetParam finds a parameter by name, returning its value and whether it was found.
func GetParam(params []Parameter, name string) (float64, bool) {
        for _, p := range params {
                if p.Name == name {
                        return p.Value, true
                }
        }
        return 0, false
}

// RequireParam finds a parameter by name or returns an error.
func RequireParam(params []Parameter, name string) (float64, error) {
        v, ok := GetParam(params, name)
        if !ok {
                return 0, fmt.Errorf("missing required parameter: %s", name)
        }
        return v, nil
}

func init() {
        registerMonteCarloExperiments()
        registerMatrixExperiments()
        registerODEExperiments()
        registerStatsExperiments()
}
