package storage

import (
        "encoding/json"
        "fmt"
        "os"
        "path/filepath"
        "sort"
        "strings"
        "time"

        "numeriforge/engine"
)

// StoredResult is the on-disk representation of an experiment result.
type StoredResult struct {
        ID             string            `json:"id"`
        ExperimentName string            `json:"experiment_name"`
        Timestamp      time.Time         `json:"timestamp"`
        Parameters     []engine.Parameter `json:"parameters"`
        Values         []float64         `json:"values"`
        Labels         []string          `json:"labels"`
        Metadata       map[string]string `json:"metadata"`
        // TODO: Add Checksum field for result integrity verification.
        // The checksum should be a SHA-256 hash of the canonical representation
        // of the Values array.
}

// Store manages experiment result persistence.
type Store struct {
        BaseDir string
}

// NewStore creates a store at the given directory.
func NewStore(baseDir string) (*Store, error) {
        if err := os.MkdirAll(baseDir, 0755); err != nil {
                return nil, fmt.Errorf("cannot create store directory: %w", err)
        }
        return &Store{BaseDir: baseDir}, nil
}

// Save persists an experiment result to disk.
func (s *Store) Save(result *engine.Result) (string, error) {
        id := fmt.Sprintf("%s_%s", result.ExperimentName, result.Timestamp.Format("20060102_150405"))

        stored := StoredResult{
                ID:             id,
                ExperimentName: result.ExperimentName,
                Timestamp:      result.Timestamp,
                Parameters:     result.Parameters,
                Values:         result.Values,
                Labels:         result.Labels,
                Metadata:       result.Metadata,
        }

        // TODO: Compute and store checksum here.
        // Should hash the canonical representation of Values.

        data, err := json.MarshalIndent(stored, "", "  ")
        if err != nil {
                return "", fmt.Errorf("marshal error: %w", err)
        }

        resultDir := filepath.Join(s.BaseDir, result.ExperimentName)
        if err := os.MkdirAll(resultDir, 0755); err != nil {
                return "", fmt.Errorf("cannot create result directory: %w", err)
        }

        path := filepath.Join(resultDir, id+".json")
        if err := os.WriteFile(path, data, 0644); err != nil {
                return "", fmt.Errorf("write error: %w", err)
        }

        // Update index
        if err := s.updateIndex(id, result.ExperimentName, result.Timestamp); err != nil {
                return "", fmt.Errorf("index update error: %w", err)
        }

        return id, nil
}

// Load reads a stored result by ID.
func (s *Store) Load(id string) (*StoredResult, error) {
        // Parse experiment name from ID
        parts := strings.SplitN(id, "_", 2)
        if len(parts) < 2 {
                return nil, fmt.Errorf("invalid result ID: %s", id)
        }
        // The experiment name may contain underscores, so we need to find the right file
        var resultPath string
        err := filepath.Walk(s.BaseDir, func(path string, info os.FileInfo, err error) error {
                if err != nil {
                        return err
                }
                if !info.IsDir() && strings.TrimSuffix(info.Name(), ".json") == id {
                        resultPath = path
                        return filepath.SkipAll
                }
                return nil
        })
        if err != nil {
                return nil, err
        }
        if resultPath == "" {
                return nil, fmt.Errorf("result not found: %s", id)
        }

        data, err := os.ReadFile(resultPath)
        if err != nil {
                return nil, fmt.Errorf("read error: %w", err)
        }

        var stored StoredResult
        if err := json.Unmarshal(data, &stored); err != nil {
                return nil, fmt.Errorf("unmarshal error: %w", err)
        }
        return &stored, nil
}

// ListResults returns all stored result IDs, optionally filtered by experiment name.
