func NewMatrix(rows, cols int) *Matrix {
        return &Matrix{Rows: rows, Cols: cols, Data: make([]float64, rows*cols)}
}

// At returns the element at (i, j).
func (m *Matrix) At(i, j int) float64 {
        return m.Data[i*m.Cols+j]
}

// Set sets the element at (i, j).
func (m *Matrix) Set(i, j int, v float64) {
        m.Data[i*m.Cols+j] = v
}

// generateRandomMatrix creates a matrix with random entries.
// TODO: Uses GlobalRand - not reproducible. Need seed parameter.
func generateRandomMatrix(rows, cols int, scale float64) *Matrix {
        m := NewMatrix(rows, cols)
        for i := 0; i < rows*cols; i++ {
