// StoredResult is the on-disk representation of an experiment result.
type StoredResult struct {
	ID             string            `json:"id"`
	ExperimentName string            `json:"experiment_name"`
	Timestamp      time.Time         `json:"timestamp"`
	Parameters     []engine.Parameter `json:"parameters"`
	Values         []float64         `json:"values"`
	Labels         []string          `json:"labels"`
	Metadata       map[string]string `json:"metadata"`
	Checksum       string            `json:"checksum,omitempty"`
}

// VerifyStatus reports the outcome of integrity verification.
type VerifyStatus string

const (
	StatusVerified    VerifyStatus = "verified"
	StatusCorrupted   VerifyStatus = "corrupted"
	StatusNoChecksum  VerifyStatus = "no_checksum"
)

// IndexEntry is a stored result index record.
type IndexEntry struct {
	ID             string
	ExperimentName string
	Timestamp      time.Time
}

// Store manages experiment result persistence.
type Store struct {
	BaseDir string
}

// NewStore creates a store at the given directory.
func NewStore(baseDir string) (*Store, error) {
	if err := os.MkdirAll(baseDir, 0755); err != nil {
		return nil, fmt.Errorf("cannot create store directory: %w", err)
	}
	return &Store{BaseDir: baseDir}, nil
}

// ComputeChecksum returns the SHA-256 checksum of the canonical value
// representation defined by the reproducibility specification.
func ComputeChecksum(values []float64) string {
	var sb strings.Builder
	for i, v := range values {
		if i > 0 {
			sb.WriteByte('\n')
		}
		fmt.Fprintf(&sb, "%.17e", v)
	}
	sum := sha256.Sum256([]byte(sb.String()))
	return fmt.Sprintf("%x", sum)
}

// Save persists an experiment result to disk.
func (s *Store) Save(result *engine.Result) (string, error) {
	id := fmt.Sprintf("%s_%s", result.ExperimentName, result.Timestamp.Format("20060102_150405"))

	checksum := ComputeChecksum(result.Values)

	if result.Metadata == nil {
		result.Metadata = map[string]string{}
	}
	result.Metadata["values_checksum"] = checksum

	stored := StoredResult{
		ID:             id,
		ExperimentName: result.ExperimentName,
		Timestamp:      result.Timestamp,
		Parameters:     result.Parameters,
		Values:         result.Values,
		Labels:         result.Labels,
		Metadata:       result.Metadata,
		Checksum:       checksum,
	}

	data, err := json.MarshalIndent(stored, "", "  ")
	if err != nil {
		return "", fmt.Errorf("marshal error: %w", err)
	}

	resultDir := filepath.Join(s.BaseDir, result.ExperimentName)
	if err := os.MkdirAll(resultDir, 0755); err != nil {
		return "", fmt.Errorf("cannot create result directory: %w", err)
	}

	path := filepath.Join(resultDir, id+".json")
	if err := os.WriteFile(path, data, 0644); err != nil {
		return "", fmt.Errorf("write error: %w", err)
	}

	if err := s.updateIndex(id, result.ExperimentName, result.Timestamp); err != nil {
		return "", fmt.Errorf("index update error: %w", err)
	}

	return id, nil
}

// Load reads a stored result by ID.
func (s *Store) Load(id string) (*StoredResult, error) {
	var resultPath string
	err := filepath.Walk(s.BaseDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if !info.IsDir() && strings.TrimSuffix(info.Name(), ".json") == id {
			resultPath = path
			return filepath.SkipAll
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	if resultPath == "" {
		return nil, fmt.Errorf("result not found: %s", id)
	}

	data, err := os.ReadFile(resultPath)
	if err != nil {
		return nil, fmt.Errorf("read error: %w", err)
	}

	var stored StoredResult
	if err := json.Unmarshal(data, &stored); err != nil {
		return nil, fmt.Errorf("unmarshal error: %w", err)
	}
	return &stored, nil
}

// ListResults returns all stored result IDs, optionally filtered by experiment name.
func (s *Store) ListResults(experimentFilter string) ([]IndexEntry, error) {
	entries, err := s.readIndex()
	if err != nil {
		return nil, err
	}

	if experimentFilter == "" {
		return entries, nil
	}

	filtered := make([]IndexEntry, 0)
	for _, entry := range entries {
		if entry.ExperimentName == experimentFilter {
			filtered = append(filtered, entry)
		}
	}
	return filtered, nil
}

// Verify checks stored result integrity by recomputing the canonical checksum.
func (s *Store) Verify(id string) (VerifyStatus, string, string, error) {
	stored, err := s.Load(id)
	if err != nil {
		return "", "", "", err
	}

	if stored.Checksum == "" {
		return StatusNoChecksum, "", "", nil
	}

	computed := ComputeChecksum(stored.Values)
	if computed == stored.Checksum {
		return StatusVerified, stored.Checksum, computed, nil
	}
	return StatusCorrupted, stored.Checksum, computed, nil
}

func (s *Store) indexPath() string {
	return filepath.Join(s.BaseDir, "index.txt")
}

func (s *Store) updateIndex(id, experimentName string, timestamp time.Time) error {
	if err := os.MkdirAll(s.BaseDir, 0755); err != nil {
		return err
	}

	f, err := os.OpenFile(s.indexPath(), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return err
	}
	defer f.Close()

	_, err = fmt.Fprintf(f, "%s|%s|%s\n", id, experimentName, timestamp.Format(time.RFC3339))
	return err
}

func (s *Store) readIndex() ([]IndexEntry, error) {
	data, err := os.ReadFile(s.indexPath())
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}

	var entries []IndexEntry
	for _, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		if line == "" {
			continue
		}
