		ts, _ := time.Parse(time.RFC3339, parts[2])
		entries = append(entries, IndexEntry{
			ID:             parts[0],
			ExperimentName: parts[1],
			Timestamp:      ts,
		})
	}

	sort.Slice(entries, func(i, j int) bool {
		return entries[i].Timestamp.Before(entries[j].Timestamp)
	})

	return entries, nil
}
