	"numeriforge/storage"
)

// ComparisonMode determines how results are compared.
type ComparisonMode int

const (
	// ModeExact uses exact float equality (legacy behavior).
	ModeExact ComparisonMode = iota
	// ModeTolerance uses configurable absolute and relative tolerance.
	ModeTolerance
)

// Tolerance defines comparison thresholds.
type Tolerance struct {
	Absolute float64
	Relative float64
}

// DefaultTolerance returns the spec defaults for scientific comparisons.
func DefaultTolerance() Tolerance {
	return Tolerance{
		Absolute: 1e-10,
		Relative: 1e-8,
	}
}

// ComparisonResult holds the outcome of comparing two experiment results.
type ComparisonResult struct {
	Match        bool
	TotalPairs   int
	MatchedPairs int
	Mismatches   []Mismatch
	Mode         ComparisonMode
	Tolerance    Tolerance
	Summary      string
}

// Mismatch records a single value pair that didn't match.
type Mismatch struct {
	Index  int
	Label  string
	ValueA float64
	ValueB float64
	AbsDiff float64
	RelDiff float64
}

// Compare compares two stored results.
func Compare(a, b *storage.StoredResult, mode ComparisonMode, tol Tolerance) *ComparisonResult {
	result := &ComparisonResult{
		Mode:      mode,
		Tolerance: tol,
	}

	if a.ExperimentName != b.ExperimentName {
		result.Match = false
		result.Summary = fmt.Sprintf("experiment name mismatch: %s vs %s", a.ExperimentName, b.ExperimentName)
		return result
	}

	minLen := len(a.Values)
	if len(b.Values) < minLen {
		minLen = len(b.Values)
	}

	if len(a.Values) != len(b.Values) {
		result.Match = false
		result.Summary = fmt.Sprintf("value count mismatch: %d vs %d", len(a.Values), len(b.Values))
		return result
	}

	result.TotalPairs = minLen

	switch mode {
	case ModeExact:
		result.Match = true
		for i := 0; i < minLen; i++ {
			label := fmt.Sprintf("value[%d]", i)
			if i < len(a.Labels) {
				label = a.Labels[i]
			}
			if a.Values[i] != b.Values[i] {
				result.Match = false
				result.Mismatches = append(result.Mismatches, Mismatch{
					Index:   i,
					Label:   label,
					ValueA:  a.Values[i],
					ValueB:  b.Values[i],
					AbsDiff: math.Abs(a.Values[i] - b.Values[i]),
					RelDiff: relDiff(a.Values[i], b.Values[i]),
				})
			} else {
				result.MatchedPairs++
			}
		}
	case ModeTolerance:
		result.Match = true
		for i := 0; i < minLen; i++ {
			label := fmt.Sprintf("value[%d]", i)
			if i < len(a.Labels) {
				label = a.Labels[i]
			}
			if !valuesMatch(a.Values[i], b.Values[i], tol) {
				result.Match = false
				result.Mismatches = append(result.Mismatches, Mismatch{
					Index:   i,
					Label:   label,
					ValueA:  a.Values[i],
					ValueB:  b.Values[i],
					AbsDiff: math.Abs(a.Values[i] - b.Values[i]),
					RelDiff: relDiff(a.Values[i], b.Values[i]),
				})
			} else {
				result.MatchedPairs++
			}
		}
	default:
		result.Match = false
		result.Summary = "unknown comparison mode"
		return result
	}

	if result.Summary == "" {
		if result.Match {
			result.Summary = fmt.Sprintf("all %d value pairs match", result.TotalPairs)
		} else {
			result.Summary = fmt.Sprintf("%d of %d value pairs mismatch", len(result.Mismatches), result.TotalPairs)
		}
	}

	return result
}

// valuesMatch implements the spec's tolerance comparison rules.
func valuesMatch(a, b float64, tol Tolerance) bool {
	if math.IsNaN(a) && math.IsNaN(b) {
		return true
	}
	if math.IsNaN(a) || math.IsNaN(b) {
		return false
	}

	if math.IsInf(a, 1) && math.IsInf(b, 1) {
		return true
	}
	if math.IsInf(a, -1) && math.IsInf(b, -1) {
		return true
	}
	if math.IsInf(a, 0) || math.IsInf(b, 0) {
		return false
	}

	if math.Abs(a) < tol.Absolute && math.Abs(b) < tol.Absolute {
		return true
	}

	diff := math.Abs(a - b)
	if diff <= tol.Absolute {
		return true
	}

	denom := math.Max(math.Abs(a), math.Abs(b))
	if denom > 0 && diff/denom <= tol.Relative {
		return true
	}

	return false
}

// FormatReport generates a human-readable comparison report.
func FormatReport(cr *ComparisonResult) string {
	var sb strings.Builder
	sb.WriteString("=== Comparison Report ===\n")
	sb.WriteString(fmt.Sprintf("Mode: %s\n", modeString(cr.Mode)))
	if cr.Mode == ModeTolerance {
		sb.WriteString(fmt.Sprintf("Absolute tolerance: %g\n", cr.Tolerance.Absolute))
		sb.WriteString(fmt.Sprintf("Relative tolerance: %g\n", cr.Tolerance.Relative))
	}
	sb.WriteString(fmt.Sprintf("Match: %v\n", cr.Match))
	sb.WriteString(fmt.Sprintf("Total pairs: %d\n", cr.TotalPairs))
	sb.WriteString(fmt.Sprintf("Matched: %d\n", cr.MatchedPairs))
	sb.WriteString(fmt.Sprintf("Summary: %s\n", cr.Summary))

	if len(cr.Mismatches) > 0 {
		sb.WriteString("\nMismatches:\n")
		for _, m := range cr.Mismatches {
			sb.WriteString(fmt.Sprintf("  [%d] %s: %.15e vs %.15e (abs=%.6e, rel=%.6e)\n",
				m.Index, m.Label, m.ValueA, m.ValueB, m.AbsDiff, m.RelDiff))
		}
	}

	return sb.String()
}

func relDiff(a, b float64) float64 {
	denom := math.Max(math.Abs(a), math.Abs(b))
	if denom < 1e-300 {
		return 0
	}
	return math.Abs(a-b) / denom
}

func modeString(m ComparisonMode) string {
	switch m {
	case ModeExact:
		return "exact"
	case ModeTolerance:
		return "tolerance"
	default:
		return "unknown"
	}
}
