func cmdRun(args []string) {
	var experimentName, outputDir, configPath string
	var paramStrs []string
	var seed int64
	seedProvided := false

	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--experiment":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --experiment requires a value\n")
				os.Exit(1)
			}
			experimentName = args[i]
		case "--output-dir":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --output-dir requires a value\n")
				os.Exit(1)
			}
			outputDir = args[i]
		case "--config":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --config requires a value\n")
				os.Exit(1)
			}
			configPath = args[i]
		case "--param":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --param requires a value\n")
				os.Exit(1)
			}
			paramStrs = append(paramStrs, args[i])
		case "--seed":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --seed requires a value\n")
				os.Exit(1)
			}
			parsed, err := strconv.ParseInt(args[i], 10, 64)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: invalid seed: %v\n", err)
				os.Exit(1)
			}
			seed = parsed
			seedProvided = true
		default:
			fmt.Fprintf(os.Stderr, "error: unknown flag: %s\n", args[i])
			os.Exit(1)
		}
	}

	if configPath != "" {
		cfg, err := config.ParseINI(configPath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "config error: %v\n", err)
			os.Exit(1)
		}
		if experimentName == "" {
			experimentName = cfg.Experiment
		}
		if outputDir == "" {
			outputDir = cfg.OutputDir
		}

		cliParams, _ := config.ParseParams(paramStrs)
		cliParamMap := make(map[string]float64)
		for _, p := range cliParams {
			cliParamMap[p.Name] = p.Value
		}
		for _, p := range cfg.Params {
			if _, exists := cliParamMap[p.Name]; !exists {
				cliParams = append(cliParams, p)
			}
		}
		paramStrs = nil
		for _, p := range cliParams {
			paramStrs = append(paramStrs, fmt.Sprintf("%s=%g", p.Name, p.Value))
		}
	}

	if experimentName == "" {
		fmt.Fprintf(os.Stderr, "error: --experiment is required\n")
		os.Exit(1)
	}
	if outputDir == "" {
		outputDir = "./results"
	}

	params, err := config.ParseParams(paramStrs)
	if err != nil {
		fmt.Fprintf(os.Stderr, "parameter error: %v\n", err)
		os.Exit(1)
	}

	fn, err := engine.Get(experimentName)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	if !seedProvided {
		seed = time.Now().UnixNano()
	}

	rng := engine.NewRNG(seed)

	result, err := fn(experimentName, params, rng)
	if err != nil {
		fmt.Fprintf(os.Stderr, "experiment error: %v\n", err)
		os.Exit(1)
	}

	if result.Metadata == nil {
		result.Metadata = map[string]string{}
	}
	if _, ok := result.Metadata["seed"]; !ok {
		result.Metadata["seed"] = strconv.FormatInt(seed, 10)
	}
	if seedProvided {
		result.Metadata["seed_source"] = "provided"
	} else {
		result.Metadata["seed_source"] = "auto-generated"
	}

	store, err := storage.NewStore(outputDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "storage error: %v\n", err)
		os.Exit(1)
	}

	id, err := store.Save(result)
	if err != nil {
		fmt.Fprintf(os.Stderr, "save error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Experiment: %s\n", experimentName)
	fmt.Printf("Result ID: %s\n", id)
	fmt.Printf("Values:\n")
	for i, v := range result.Values {
		label := fmt.Sprintf("[%d]", i)
		if i < len(result.Labels) {
			label = result.Labels[i]
		}
		fmt.Printf("  %s = %.15e\n", label, v)
	}
}

func cmdCompare(args []string) {
	if len(args) < 2 {
		fmt.Fprintf(os.Stderr, "usage: numeriforge compare <result_id_1> <result_id_2> --store-dir <dir> [--mode exact|tolerance] [--abs-tol <val>] [--rel-tol <val>]\n")
		os.Exit(1)
	}

	id1 := args[0]
	id2 := args[1]
	storeDir := "./results"
	mode := "exact"
	tol := compare.DefaultTolerance()

	for i := 2; i < len(args); i++ {
		switch args[i] {
		case "--store-dir":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --store-dir requires a value\n")
				os.Exit(1)
			}
			storeDir = args[i]
		case "--mode":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --mode requires a value\n")
				os.Exit(1)
			}
			mode = args[i]
		case "--abs-tol":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --abs-tol requires a value\n")
				os.Exit(1)
			}
			v, err := strconv.ParseFloat(args[i], 64)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: invalid absolute tolerance: %v\n", err)
				os.Exit(1)
			}
			tol.Absolute = v
		case "--rel-tol":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --rel-tol requires a value\n")
				os.Exit(1)
			}
			v, err := strconv.ParseFloat(args[i], 64)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: invalid relative tolerance: %v\n", err)
				os.Exit(1)
			}
			tol.Relative = v
		default:
			fmt.Fprintf(os.Stderr, "error: unknown flag: %s\n", args[i])
			os.Exit(1)
		}
	}

	store, err := storage.NewStore(storeDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "storage error: %v\n", err)
		os.Exit(1)
	}

	a, err := store.Load(id1)
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}

	b, err := store.Load(id2)
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}

	var comparisonMode compare.ComparisonMode
	switch mode {
	case "exact":
		comparisonMode = compare.ModeExact
	case "tolerance":
		comparisonMode = compare.ModeTolerance
	default:
		fmt.Fprintf(os.Stderr, "error: invalid comparison mode: %s\n", mode)
		os.Exit(1)
	}

	cr := compare.Compare(a, b, comparisonMode, tol)
	fmt.Print(compare.FormatReport(cr))

	if cr.Match {
		os.Exit(0)
	} else {
		os.Exit(1)
	}
}

func cmdList(args []string) {
	storeDir := "./results"
	experimentFilter := ""

	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--store-dir":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --store-dir requires a value\n")
				os.Exit(1)
			}
			storeDir = args[i]
		case "--experiment":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --experiment requires a value\n")
				os.Exit(1)
			}
			experimentFilter = args[i]
		default:
			fmt.Fprintf(os.Stderr, "error: unknown flag: %s\n", args[i])
			os.Exit(1)
		}
	}

	store, err := storage.NewStore(storeDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "storage error: %v\n", err)
		os.Exit(1)
	}

	entries, err := store.ListResults(experimentFilter)
	if err != nil {
		fmt.Fprintf(os.Stderr, "list error: %v\n", err)
		os.Exit(1)
	}

	if len(entries) == 0 {
		fmt.Println("No results found.")
		return
	}

	fmt.Printf("%-40s %-25s %s\n", "ID", "Experiment", "Timestamp")
	fmt.Println(strings.Repeat("-", 80))
	for _, entry := range entries {
		fmt.Printf("%-40s %-25s %s\n", entry.ID, entry.ExperimentName, entry.Timestamp.Format("2006-01-02 15:04:05"))
	}
}

func cmdExport(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "usage: numeriforge export <id> --store-dir <dir> [--format json|csv]\n")
		os.Exit(1)
	}

	id := args[0]
	storeDir := "./results"
	format := "json"

	for i := 1; i < len(args); i++ {
		switch args[i] {
		case "--store-dir":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --store-dir requires a value\n")
				os.Exit(1)
			}
			storeDir = args[i]
		case "--format":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --format requires a value\n")
				os.Exit(1)
			}
			format = args[i]
		default:
			fmt.Fprintf(os.Stderr, "error: unknown flag: %s\n", args[i])
			os.Exit(1)
		}
	}

	store, err := storage.NewStore(storeDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "storage error: %v\n", err)
		os.Exit(1)
	}

	result, err := store.Load(id)
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}

	switch format {
	case "json":
		data, err := json.MarshalIndent(result, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "marshal error: %v\n", err)
			os.Exit(1)
		}
		fmt.Println(string(data))
	case "csv":
		fmt.Println("label,value")
		for i, v := range result.Values {
			label := fmt.Sprintf("value_%d", i)
			if i < len(result.Labels) {
				label = result.Labels[i]
			}
			fmt.Printf("%s,%.15e\n", label, v)
		}
	default:
		fmt.Fprintf(os.Stderr, "unknown format: %s\n", format)
		os.Exit(1)
	}
}

func cmdVerify(args []string) {
	if len(args) < 1 {
		fmt.Fprintf(os.Stderr, "usage: numeriforge verify <result_id> --store-dir <dir>\n")
		os.Exit(1)
	}

	id := args[0]
	storeDir := "./results"

	for i := 1; i < len(args); i++ {
		switch args[i] {
		case "--store-dir":
			i++
			if i >= len(args) {
				fmt.Fprintf(os.Stderr, "error: --store-dir requires a value\n")
				os.Exit(1)
			}
			storeDir = args[i]
		default:
			fmt.Fprintf(os.Stderr, "error: unknown flag: %s\n", args[i])
			os.Exit(1)
		}
	}

	store, err := storage.NewStore(storeDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "storage error: %v\n", err)
		os.Exit(1)
	}

	status, expected, computed, err := store.Verify(id)
	if err != nil {
		fmt.Fprintf(os.Stderr, "verify error: %v\n", err)
		os.Exit(1)
	}

	switch status {
	case storage.StatusVerified:
		fmt.Printf("VERIFIED: %s\n", id)
		os.Exit(0)
	case storage.StatusCorrupted:
		fmt.Printf("CORRUPTED: %s (expected=%s, computed=%s)\n", id, expected, computed)
		os.Exit(1)
	case storage.StatusNoChecksum:
		fmt.Printf("NO_CHECKSUM: %s\n", id)
		os.Exit(2)
	default:
		fmt.Fprintf(os.Stderr, "unknown verification status: %s\n", status)
		os.Exit(1)
	}
}
